<?php
namespace App\Http\Controllers; use App\Models\{Product,StockMovement}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class MovementController extends Controller {public function create(){return view('movements.create',['products'=>Product::orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id','type'=>'required|in:in,out','quantity'=>'required|integer|min:1','reason'=>'nullable|max:180','reference'=>'nullable|max:80']);DB::transaction(function()use($d){$p=Product::lockForUpdate()->findOrFail($d['product_id']);if($d['type']==='out'&&$p->quantity<$d['quantity'])abort(422,'Stock insuffisant pour cette sortie.');$p->increment('quantity',$d['type']==='in'?$d['quantity']:-$d['quantity']);StockMovement::create($d+['user_id'=>auth()->id()]);});return redirect()->route('dashboard')->with('success','Mouvement enregistré.');}}
